from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')
orig=s

def rep(old,new,label):
    global s
    if old not in s:
        raise SystemExit(f'missing marker: {label}')
    s=s.replace(old,new,1)

