load_marker='function load(){try{var raw=localStorage.getItem(STORE);'
helpers=r'''function normalizePlantData(p){p=p||{};if(typeof p.favorite!=="boolean")p.favorite=false;if(!Array.isArray(p.bloomMonths))p.bloomMonths=[];if(!p.ecoNative)p.ecoNative="auto";if(!p.ecoFlowerAccess)p.ecoFlowerAccess="auto";if(!p.created)p.created=isoToday();if(!p.family)p.family="";return p}
function normalizeEcology(v){return{habitat:Object.assign({},DEFAULT_HABITAT,v&&v.habitat||{})}}
function ecoProfileFor(p){var t=((p&&p.name||"")+" "+(p&&p.scientific||"")).toLowerCase();for(var i=0;i<ECO_PROFILES.length;i++){if(ECO_PROFILES[i].keys.some(function(k){return t.indexOf(k)>=0}))return ECO_PROFILES[i]}return null}
function bloomValueFromMonths(months){months=Array.isArray(months)?months:[];if(!months.length)return 5;var n=Math.min(13,5+months.length*2),early=months.some(function(m){return m<=4}),late=months.some(function(m){return m>=9});if(early)n+=1;if(late)n+=1;return Math.min(15,n)}
function ecoLevel(score){return score>=85?"sehr wertvoll":score>=70?"wertvoll":score>=50?"mittel":score>=25?"eher gering":"gering"}
function ecoBadgeClass(score){return score>=70?"high":score>=45?"mid":"low"}
function plantInsectValue(p){var r=ecoProfileFor(p),months=(p.bloomMonths||[]).length?(p.bloomMonths||[]):((r&&r.bloom)||[]),c=r?{n:r.n,h:r.h,nat:r.nat,b:r.b,a:r.a,p:r.p}:{n:10,h:4,nat:5,b:bloomValueFromMonths(months),a:7,p:5},source=r?"Artprofil":"Schätzung",supports=r?(r.s||[]): ["bestäuber"],notes=r?(r.notes||[]): ["Aus den vorhandenen Angaben automatisch geschätzt."];if((p.bloomMonths||[]).length)c.b=bloomValueFromMonths(p.bloomMonths);if(p.ecoNative==="yes")c.nat=15;else if(p.ecoNative==="no")c.nat=1;if(p.ecoFlowerAccess==="open")c.a=10;else if(p.ecoFlowerAccess==="partial")c.a=5;else if(p.ecoFlowerAccess==="filled"){c.a=1;c.n=Math.max(3,c.n-8)}var score=Math.max(0,Math.min(100,Math.round(c.n+c.h+c.nat+c.b+c.a+c.p)));return{score:score,level:ecoLevel(score),source:source,bloomMonths:months,supports:supports,notes:notes,components:c}}
function habitatScore(h){h=Object.assign({},DEFAULT_HABITAT,h||{});return(h.waterSource?3:0)+(h.deadwood?4:0)+(h.bareSoil?4:0)+(h.wildCorner?4:0)+(h.noPesticides?3:0)+(h.nativePlantsFocus?2:0)}
function gardenEcoScore(plantsOverride){var plants=(plantsOverride||state.plants||[]).map(normalizePlantData),unique={},families=new Set(),types=new Set();plants.forEach(function(p){var k=(p.scientific||p.name||p.id||"").trim().toLowerCase();if(!unique[k]||plantInsectValue(p).score>plantInsectValue(unique[k]).score)unique[k]=p;if(p.family)families.add(String(p.family).toLowerCase());if(p.type)types.add(p.type)});var ups=Object.keys(unique).map(function(k){return unique[k]}),quality=0;if(ups.length){var scores=ups.map(function(p){return plantInsectValue(p).score}).sort(function(a,b){return b-a}).slice(0,20);quality=Math.round((scores.reduce(function(a,b){return a+b},0)/scores.length)*.40)}var counts=Array(12).fill(0);ups.forEach(function(p){plantInsectValue(p).bloomMonths.forEach(function(m){if(m>=1&&m<=12)counts[m-1]++})});var relevant=[2,3,4,5,6,7,8,9],bloom=0,covered=true;relevant.forEach(function(i){if(counts[i]>=3)bloom+=3;else if(counts[i]>=1)bloom+=2;else covered=false});if(covered)bloom+=1;bloom=Math.min(25,bloom);var speciesPts=Math.min(7,Math.round(ups.length*.85)),familyPts=Math.min(4,Math.round(families.size*.9)),typePts=Math.min(4,Math.round(types.size*1.35)),diversity=Math.min(15,speciesPts+familyPts+typePts),hab=habitatScore(state.ecology&&state.ecology.habitat),total=Math.max(0,Math.min(100,quality+bloom+diversity+hab));return{total:total,quality:quality,bloom:bloom,diversity:diversity,habitat:hab,counts:counts,uniqueCount:ups.length,valuable:plants.filter(function(p){return plantInsectValue(p).score>=70}).length,profiled:plants.filter(function(p){return plantInsectValue(p).source==="Artprofil"}).length}}
function gardenEcoLevel(score){return score>=85?"Ausgezeichnet":score>=70?"Sehr gut":score>=55?"Gut":score>=35?"Im Aufbau":"Noch ausbaufähig"}
function bloomGapRecommendation(g){var gaps=[];for(var m=3;m<=10;m++)if(!g.counts[m-1])gaps.push(m);if(gaps.length){var names=gaps.map(function(m){return MONTHS[m-1]});if(gaps.some(function(m){return m<=4}))return"Größtes Potenzial: mehr Frühblüher für "+names.filter(function(x,i){return gaps[i]<=4}).join(", ")+".";if(gaps.some(function(m){return m>=9}))return"Größtes Potenzial: mehr Spätblüher für "+names.filter(function(x,i){return gaps[i]>=9}).join(", ")+".";return"Blühlücke: In "+names.join(", ")+" fehlt derzeit eine eingetragene Blühpflanze."}if(g.habitat<10)return"Das Blühangebot ist gut verteilt. Zusätzliche Lebensräume wie Totholz, offene Bodenstellen oder eine Wasserstelle würden den Garten weiter aufwerten.";if(g.diversity<10)return"Das Blühangebot ist durchgängig. Mehr unterschiedliche Pflanzenarten und Strukturen erhöhen die Vielfalt zusätzlich.";return"Sehr ausgewogen: durchgängiges Blühangebot und gute Lebensraumstrukturen. Vielfalt erhalten und verblühte Stängel teilweise über Winter stehen lassen."}
function contributionText(p){var e=plantInsectValue(p),others=state.plants.filter(function(x){return x.id!==p.id}),g=gardenEcoScore(others),gaps=e.bloomMonths.filter(function(m){return m>=3&&m<=10&&!g.counts[m-1]});if(gaps.length)return"Diese Pflanze schließt aktuell eine Blühlücke in "+gaps.map(function(m){return MONTHS[m-1]}).join(", ")+".";if(e.bloomMonths.some(function(m){return m<=4}))return"Diese Pflanze stärkt das frühe Nahrungsangebot im Garten.";if(e.bloomMonths.some(function(m){return m>=9}))return"Diese Pflanze stärkt das wichtige späte Nahrungsangebot.";return e.score>=70?"Diese Pflanze ist eine wertvolle Ergänzung für die Insektenvielfalt.":"Der ökologische Beitrag ist begrenzt; zusammen mit wertvollen heimischen Blühpflanzen bleibt sie trotzdem Teil eines vielfältigen Gartens."}
'''
rep(load_marker,helpers+'\n'+load_marker,'eco helpers')

