new_pf='function plantFromForm(){var name=el("plantName").value.trim();if(!name)throw new Error("Bitte einen Pflanzenname eingeben.");var old=state.editPlantId?state.plants.find(function(x){return x.id===state.editPlantId}):null;var by=el("plantBirthYear").value.trim();if(by){var y=Number(by),now=new Date().getFullYear();if(!Number.isInteger(y)||y<1900||y>now)throw new Error("Bitte ein plausibles Pflanz-/Anzuchtjahr eingeben.")}return normalizePlantData({id:old?old.id:uid(),name:name,scientific:el("plantScientific").value.trim(),family:el("plantFamily").value.trim()||(old?old.family||"":""),area:el("plantArea").value.trim(),type:el("plantType").value||"bed",water:el("plantWater").value,size:el("plantSize").value||"medium",birthYear:by?Number(by):null,plantedSince:el("plantSince").value||null,transplanted:el("plantTransplanted").value||null,notes:el("plantNotes").value.trim(),fertMonths:checkedMonths("fert"),cutMonths:checkedMonths("cut"),bloomMonths:checkedMonths("bloom"),ecoNative:el("plantNative").value||"auto",ecoFlowerAccess:el("plantFlowerAccess").value||"auto",favorite:old?!!old.favorite:false,photo:state.photoData||"",lat:old?old.lat:null,lon:old?old.lon:null,lastWatered:old?old.lastWatered:null,lastFertilized:old?old.lastFertilized:null,lastCut:old?old.lastCut:null,snoozed:old&&old.snoozed?old.snoozed:{},created:old?old.created:isoToday()})}'
